const FREE_SHIP_OVER = 7500; // cents; mirrors shop.config.json
const FLAT_SHIP = 800;

export async function onRequestPost(context) {
  const { request, env } = context;
  let data;
  try { data = await request.json(); } catch { return json({ error: 'bad request' }, 400); }

  const items = Array.isArray(data.items) ? data.items.slice(0, 20) : [];
  if (!items.length) return json({ error: 'the cart is empty' }, 400);

  const lines = [];
  let physicalSubtotal = 0;
  let anyPhysical = false;
  const itemStrings = [];
  for (const it of items) {
    const sku = String(it.sku || '').slice(0, 24);
    const tier = String(it.tier || '').slice(0, 12);
    const qty = Math.min(Math.max(parseInt(it.qty, 10) || 1, 1), 25);
    const entry = PRICES[sku];
    const t = entry && entry.tiers && entry.tiers[tier];
    if (!t) return json({ error: `unknown item ${sku}:${tier} — refresh the store and try again` }, 400);
    const cents = Math.round(t.price * 100);
    if (t.physical) { anyPhysical = true; physicalSubtotal += cents * qty; }
    lines.push({ name: `${entry.title} — ${tier.charAt(0).toUpperCase()}${tier.slice(1)}`, cents, qty });
    itemStrings.push(`${sku}:${tier}:${qty}`);
  }

  if (!env.STRIPE_SECRET_KEY) {
    return json({ error: 'checkout is not wired yet — the desk will take this order', desk: true }, 503);
  }

  const origin = new URL(request.url).origin;
  const p = new URLSearchParams();
  p.set('mode', 'payment');
  p.set('success_url', `${origin}/thanks.html?paid=1`);
  p.set('cancel_url', `${origin}/cart.html`);
  p.set('metadata[items]', itemStrings.join('|').slice(0, 480));
  lines.forEach((l, i) => {
    p.set(`line_items[${i}][price_data][currency]`, 'usd');
    p.set(`line_items[${i}][price_data][unit_amount]`, String(l.cents));
    p.set(`line_items[${i}][price_data][product_data][name]`, l.name.slice(0, 120));
    p.set(`line_items[${i}][quantity]`, String(l.qty));
  });
  if (anyPhysical) {
    p.set('shipping_address_collection[allowed_countries][0]', 'US');
    const ship = physicalSubtotal >= FREE_SHIP_OVER ? 0 : FLAT_SHIP;
    p.set('shipping_options[0][shipping_rate_data][type]', 'fixed_amount');
    p.set('shipping_options[0][shipping_rate_data][display_name]',
      ship === 0 ? 'Free — rolled in a tube from Austin' : 'Rolled in a tube from Austin');
    p.set('shipping_options[0][shipping_rate_data][fixed_amount][amount]', String(ship));
    p.set('shipping_options[0][shipping_rate_data][fixed_amount][currency]', 'usd');
  }
  if (env.STRIPE_TAX === '1') p.set('automatic_tax[enabled]', 'true');

  const res = await fetch('https://api.stripe.com/v1/checkout/sessions', {
    method: 'POST',
    headers: {
      authorization: `Bearer ${env.STRIPE_SECRET_KEY}`,
      'content-type': 'application/x-www-form-urlencoded',
    },
    body: p.toString(),
  });
  if (!res.ok) {
    const detail = await res.text();
    return json({ error: 'the payment rail refused', detail: detail.slice(0, 300) }, 502);
  }
  const session = await res.json();
  return json({ url: session.url });
}

function json(obj, status = 200) {
  return new Response(JSON.stringify(obj), { status, headers: { 'content-type': 'application/json' } });
}
